import React, { useState, useEffect, useCallback } from 'react';
import PersonalInfoStep from './steps/PersonalInfoStep';
import { submitForm, getUserFormSubmissions } from '../services/firebaseService';
import { useAuth } from '../contexts/AuthContext';
import { signOutUser } from '../services/authService';

const MultiStepForm = () => {
  const [formData, setFormData] = useState({});
  // Keep the File separate from Firestore data; storage upload is not wired yet.
  const [cvFile, setCVFile] = useState(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitMessage, setSubmitMessage] = useState('');
  const [submissions, setSubmissions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const { user, userId } = useAuth();

  const handleLogout = async () => {
    await signOutUser();
  };

  const loadSubmissions = useCallback(async () => {
    try {
      setLoading(true);
      setError('');
      const submissionsResult = await getUserFormSubmissions(userId);
      if (submissionsResult.success) {
        setSubmissions(submissionsResult.data);
      } else {
        setError(submissionsResult.message);
      }
    } catch (err) {
      setError('Failed to load submissions');
      console.error('Error loading submissions:', err);
    } finally {
      setLoading(false);
    }
  }, [userId]);

  useEffect(() => {
    loadSubmissions();
  }, [loadSubmissions]);

  // TODO: Implement form validation using Formik and Yup
  // TODO: Implement form data handling

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);
    setSubmitMessage('');

    try {
      // TODO: Add validation before submitting
      const submissionData = {
        ...formData,
        userId: userId
      };

      const result = await submitForm(submissionData);

      if (result.success) {
        setSubmitMessage('Form submitted successfully!');
        // Reset form
        setFormData({});
        setCVFile(null);
        // Reload submissions to show the new one
        loadSubmissions();
      } else {
        setSubmitMessage(result.message);
      }
    } catch (error) {
      setSubmitMessage('An error occurred. Please try again.');
      console.error('Submit error:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="container">
      <div className="form-container">
        <div className="form-heading">
          <div><p className="eyebrow">YOUR HPAIR PROFILE</p><h1>Let’s get to know you.</h1></div>
          <button 
            onClick={handleLogout}
            className="btn btn-secondary"
            style={{ fontSize: '14px', padding: '8px 16px' }}
          >
            Logout
          </button>
        </div>
        <p className="page-description">Tell us about yourself and how to reach you. Fields are required unless marked optional.</p>

        <div className="account-strip">
          <span>Signed in as <strong>{user.email}</strong></span>
        </div>

        <form autoComplete="off" onSubmit={handleSubmit} className="profile-form">
          <PersonalInfoStep 
            formData={formData} 
            cvFile={cvFile}
            onCVChange={setCVFile}
            setFormData={setFormData} 
          />

          {submitMessage && (
            <div className={`submit-message ${submitMessage.includes('successfully') ? 'success' : 'error'}`} role="status">
              {submitMessage}
            </div>
          )}

          <div className="form-actions profile-actions">
            <button
              type="submit"
              className="btn btn-primary"
              disabled={isSubmitting}
            >
              {isSubmitting ? 'Submitting...' : 'Submit information'}
            </button>
          </div>
        </form>

        {/* Admin Panel - User's Submissions */}
        <details className="submission-history">
          <summary>Your previous submissions {!loading && !error && <span>{submissions.length}</span>}</summary>
          <p>View your submitted information below.</p>

          {!loading && !error && <div style={{ marginBottom: '20px', padding: '15px', backgroundColor: 'var(--color-surface-muted)', borderRadius: '8px' }}>
            <p><strong>Logged in as:</strong> {user.email}</p>
            <p><strong>Your submissions:</strong> {submissions.length}</p>
          </div>}

          <button 
            onClick={loadSubmissions}
            disabled={loading}
            className="btn btn-primary"
            style={{ marginBottom: '20px' }}
          >
            Refresh
          </button>

          {loading ? (
            <p>Loading submissions...</p>
          ) : error ? (
            <p role="status">
              Your submission history isn’t available right now. You can try refreshing.
            </p>
          ) : submissions.length === 0 ? (
            <p>There were no previous submissions.</p>
          ) : (
            <div className="submissions-list">
              {submissions.map((submission) => (
                <div key={submission.id} className="submission-item">
                  <div className="submission-header">
                    <h3>Submission #{submission.id.slice(-8)}</h3>
                    <span className="submission-date">
                      {formatDate(submission.submittedAt)}
                    </span>
                  </div>
              <div className="submission-details">
                <p><strong>Name:</strong> {submission.firstName} {submission.lastName}</p>
                <p><strong>Date of Birth:</strong> {submission.dateOfBirth}</p>
                <p><strong>Gender:</strong> {submission.gender}</p>
              </div>
                </div>
              ))}
            </div>
          )}
        </details>
      </div>
    </div>
  );
};

const formatDate = (timestamp) => {
  if (!timestamp) return 'N/A';
  return new Date(timestamp.seconds * 1000).toLocaleString();
};

export default MultiStepForm;
